def seed():
    with app.app_context():
        db.create_all()

        existing = Dialogue.query.filter_by(topic="Negotiating a Business Deal").first()
        if existing:
            print("B2 dialogue 2 already exists — skipping.")
            return

        dialogue = Dialogue(
            topic="Negotiating a Business Deal",
            lang_level="B2",
            length=30
        )
        db.session.add(dialogue)
        db.session.flush()

        for line_data in lines_data:
            line = DialogueLine(
                dialogue_id=dialogue.id,
                **line_data
            )
            db.session.add(line)

        db.session.commit()
        print(f"Successfully seeded B2 dialogue 2 ID {dialogue.id} with {len(lines_data)} lines in 25 languages.")


if __name__ == '__main__':
    seed()
